package ai.decisionos.aside;
import android.content.Context;import android.net.Uri;import org.json.*;import java.io.*;import java.net.URL;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.security.cert.X509Certificate;import javax.net.ssl.*;
/** Pinned transport only; never claims the foreground browser poll lease. */
final class ChatWorkTransport {
 final String endpoint,token,pin,session;SSLSocketFactory sockets;
 ChatWorkTransport(Context c)throws Exception{String value=GoalAgentPairing.load(c);if(value==null)throw new IOException("pairing required");String[] parts=value.trim().split("\\|",-1);if(parts.length!=3)throw new IOException();Uri uri=Uri.parse(parts[0]);if(!"https".equals(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null||!(uri.getPath()==null||uri.getPath().isEmpty())||!parts[1].matches("[A-Za-z0-9_-]{32,}")||!parts[2].matches("(?i)[0-9a-f]{64}"))throw new IOException();endpoint=parts[0];token=parts[1];pin=parts[2].toLowerCase();session=c.getSharedPreferences("nubi_relay_session",0).getString("id","");if(session.isEmpty())throw new IOException("device session required");
        TrustManager[] trust={new X509TrustManager(){public X509Certificate[] getAcceptedIssuers(){return new X509Certificate[0];} public void checkClientTrusted(X509Certificate[] c,String a) throws java.security.cert.CertificateException {throw new java.security.cert.CertificateException("client certificate not supported");} public void checkServerTrusted(X509Certificate[] c,String a) throws java.security.cert.CertificateException {try{if(c==null||c.length==0)throw new Exception(); byte[] hash=MessageDigest.getInstance("SHA-256").digest(c[0].getEncoded());StringBuilder h=new StringBuilder();for(byte b:hash)h.append(String.format(java.util.Locale.ROOT,"%02x",b&255));if(!MessageDigest.isEqual(h.toString().getBytes(StandardCharsets.US_ASCII),pin.getBytes(StandardCharsets.US_ASCII)))throw new Exception();c[0].checkValidity();}catch(Exception e){throw new java.security.cert.CertificateException("Server certificate pin mismatch",e);}}}};
        SSLContext context=SSLContext.getInstance("TLS");context.init(null,trust,null);sockets=context.getSocketFactory();}
 JSONObject post(String path,JSONObject payload)throws Exception{if(!java.util.Arrays.asList("/chat-submit","/chat-status","/group-submit","/group-status").contains(path))throw new IOException();if(path.equals("/chat-submit")||path.startsWith("/group-"))payload.put("device_session",session);HttpsURLConnection c=(HttpsURLConnection)new URL(endpoint+path).openConnection();c.setSSLSocketFactory(sockets);c.setHostnameVerifier((h,s)->true);c.setInstanceFollowRedirects(false);c.setConnectTimeout(7000);c.setReadTimeout(22000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Authorization","Bearer "+token);c.setRequestProperty("Content-Type","application/json");byte[] body=payload.toString().getBytes(StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(body.length);try{try(OutputStream out=c.getOutputStream()){out.write(body);}if(c.getResponseCode()!=200)throw new IOException("relay HTTP "+c.getResponseCode());ByteArrayOutputStream data=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1){data.write(buffer,0,n);if(data.size()>32768)throw new IOException("response too large");}}return new JSONObject(data.toString("UTF-8"));}finally{c.disconnect();}}
}
